edits.sketch:
for _, field := range allFields {
	if _, hasValue := result.Values[field]; hasValue {
		continue
	}
	raw, exists := config[field]
	if !exists || raw == nil {
		continue
	}
	switch raw.(type) {
	case bool,
		float64, float32,
		int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64,
		json.Number:
		result.Values[field] = raw
		logger.Debug("Strategy 5: took literal scalar config value", zap.String("field", field))
	}
}
